  },
  up: /\b(rose|rise[sn]?|rising|increas(e|ed|es|ing)|up|gain(ed|s)?|climb(ed|s)?|jump(ed|s)?|higher|advanc(ed|es)|accelerat(ed|es|ing)|strengthen(ed|s)?|grew|grow(n|s|th)?|stieg|gestiegen|steigt|legte zu|höher|gestegen|steeg|stijgt|hoger)\b/,
  down: /\b(fell|fall(s|en|ing)?|declin(e|ed|es|ing)|drop(ped|s)?|down|lower|slipp?(ed|s)?|slid|sank|decreas(e|ed|es|ing)|weaken(ed|s)?|lost|shrank|contract(ed|ion)?|fiel|gefallen|gesunken|niedriger|gedaald|daalde|daalt)\b/,
  unchanged: /\b(unchanged|flat|steady|held|stable|unverändert|stabil|ongewijzigd)\b/,
  estimate: /\b(expect(ed|ation|ations|s)?|forecast(s|ed|ers)?|estimate[sd]?|consensus|projected|anticipated|predicted|polled|survey(ed)?|odds|probabilit(y|ies)|chances?|likelihood|prognose|erwart(et|ung|ungen)|schätzung|wahrscheinlichkeit|verwacht(ing|e)?|raming|kans)\b/,
  percent: /(%|\bper ?cent\b|\bprozent\b|\bprocent\b)/,
  pp: /(percentage[- ]points?|\bpp\b|\bppts?\b|prozentpunkt|procentpunt)/,
  bp: /(basis points?|\bbps?\b|basispunkt|basispunt)/,
  speech: /\b(said|says|according to|told|noted|argued|wrote|expects?|expected|estimated?|believes?|warned|polled)\b/,
  causal: /\b(because|due to|driven by|caused by|thanks to|on the back of|triggered|sparked|fuell?ed by|led to|prompted|weighed on|boosted by|as a result|in response to|amid)\b/,
  speculative: /\b(will|is set to|are set to|likely|could|may|might)\b/,
  advice: /\b(you should|investors should|traders should|should (buy|sell|invest|consider)|consider (buying|selling|adding)|(buy|sell) (now|the dip|signal)|good time to (buy|sell|invest)|worth buying|we recommend|recommend(s|ed)? (buying|selling)|strong (buy|sell)|go (long|short)|take profits?|price target|zacks rank|kaufempfehlung|koopadvies)\b/,
  months: /\b(january|february|march|april|june|july|august|september|october|november|december|januar|februar|märz|mai|juni|juli|oktober|dezember|januari|februari|maart|mei|augustus|oktober)\b/g,
};
const CURRENCY = {
  USD: /(\$|\bus\$|\busd\b|\bdollars?\b)/, EUR: /(€|\beur\b|\beuros?\b)/, GBP: /(£|\bgbp\b|\bpounds?\b|\bsterling\b)/,
  JPY: /(¥|\bjpy\b|\byen\b)/, CHF: /(\bchf\b|\bfrancs?\b)/,
};
const anyMatch = (arr, t) => arr.some(r => r.test(t));
const monthCanon = { januar: 'january', januari: 'january', februar: 'february', februari: 'february', märz: 'march', maart: 'march', mai: 'may', mei: 'may', juni: 'june', juli: 'july', augustus: 'august', oktober: 'october', dezember: 'december' };
const monthsIn = t => [...new Set((norm(t).match(L.months) || []).map(m => monthCanon[m] || m))];

// ---------------------------------------------------------------------------
// 3. per-claim checks
// ---------------------------------------------------------------------------
function validateClaims(article, rawClaims, storyId) {
// ---------------------------------------------------------------------------
const textNorm = norm(article.text_content);
const paragraphs = article.text_content.split(/\n\s*\n/);
const seenStatements = new Set();

return rawClaims.map((c, idx) => {
  const errors = [];
  const warnings = [];
  const statement = String(c.statement || '').trim();
  const quote = String(c.evidence_quote || '').trim();
  const sN = norm(statement);
  const qN = norm(quote);
  const f = c.figure || null;

  // --- structure
  if (!statement) errors.push('empty_statement');
  if (seenStatements.has(sN)) errors.push('duplicate_statement');
  seenStatements.add(sN);

  // --- evidence: exact span in article text
  let location = null;
  if (qN.length < 20) errors.push('quote_too_short');
  if (qN.length > 600) errors.push('quote_too_long');
  if (/\.\.\.|…/.test(quote)) errors.push('ellipsis_in_quote');
  const pos = textNorm.indexOf(qN);
  if (pos === -1) errors.push('evidence_not_found_in_article');
  else {
    const pIdx = paragraphs.findIndex(p => norm(p).includes(qN));
    location = { paragraph: pIdx >= 0 ? pIdx + 1 : null, char_start_normalized: pos, char_end_normalized: pos + qN.length };
  }

  // --- numbers: every number in the statement must be in the evidence quote
  const sNum = extractNumbers(statement, 'en');
  const qNum = extractNumbers(quote, article.language);
  for (const n of sNum.nums) {
    if (n.isYear) continue; // years usually come from context; months are checked below
    if (!numIn(n.v, qNum.nums) && !numIn(n.raw, qNum.nums)) errors.push(`statement_number_not_in_evidence:${n.tok}`);
  }
  for (const tm of sNum.times) if (!qNum.times.includes(tm)) errors.push(`statement_time_not_in_evidence:${tm}`);

  // --- period: months named in the statement must appear in the quote
  const sMonths = monthsIn(statement), qMonths = monthsIn(quote);
  if (sMonths.length && qMonths.length && sMonths.some(m => !qMonths.includes(m))) errors.push(`period_month_mismatch:${sMonths.join('/')}`);
  if (sMonths.length && !qMonths.length) warnings.push('period_taken_from_context');

  // --- figure checks
  if (f) {
    const vt = norm(f.value_text);
    if (!vt) errors.push('figure_value_text_missing');
    else if (!qN.includes(vt)) errors.push(`figure_value_text_not_in_quote:${f.value_text}`);
    const vtNum = extractNumbers(f.value_text, article.language).nums[0];
    if (!vtNum || !(close(vtNum.v, f.value) || close(vtNum.raw, f.value))) errors.push(`figure_value_mismatch:${f.value}!=${f.value_text}`);
    if (!numIn(f.value, sNum.nums) && !sNum.nums.some(n => close(n.v, vtNum ? vtNum.v : NaN))) errors.push('figure_not_stated_in_statement');

    // unit
    if (f.unit === 'percent') {
      if (!L.percent.test(qN)) errors.push('unit_percent_not_in_evidence');
      if (!L.percent.test(sN) || L.pp.test(sN)) errors.push('unit_percent_not_in_statement');
    } else if (f.unit === 'percentage_points') {
      if (!L.pp.test(qN)) errors.push('unit_pp_not_in_evidence');
      if (!L.pp.test(sN)) errors.push('unit_pp_not_in_statement');
    } else if (f.unit === 'basis_points') {
      if (!L.bp.test(qN)) errors.push('unit_bp_not_in_evidence');
      if (!L.bp.test(sN)) errors.push('unit_bp_not_in_statement');
    }
    // currency
    if (f.currency) {
      const cur = String(f.currency).toUpperCase();
      const re = CURRENCY[cur] || new RegExp(`\\b${cur.toLowerCase()}\\b`);
      if (!re.test(qN)) errors.push(`currency_not_in_evidence:${cur}`);
      if (!re.test(sN)) errors.push(`currency_not_in_statement:${cur}`);
    }
    // comparison basis
    const basisLex = L.basis[f.comparison_basis];
    if (basisLex) {
      if (!anyMatch(basisLex, qN)) errors.push(`basis_not_supported_by_evidence:${f.comparison_basis}`);
      if (!anyMatch(basisLex, sN)) errors.push(`basis_missing_in_statement:${f.comparison_basis}`);
      for (const other of L.conflicts[f.comparison_basis] || []) {
        if (anyMatch(L.basis[other], sN)) errors.push(`basis_conflict_in_statement:${other}`);
        if (anyMatch(L.basis[other], qN) && !anyMatch(basisLex, qN)) errors.push(`basis_conflicts_with_evidence:${other}`);
      }
    }
    // direction
    if (f.direction === 'up' || f.direction === 'down') {
      const same = f.direction === 'up' ? L.up : L.down;
      const opp = f.direction === 'up' ? L.down : L.up;
      if (!same.test(sN)) errors.push(`direction_${f.direction}_missing_in_statement`);
      if (opp.test(sN)) errors.push('direction_conflict_in_statement');
      if (!same.test(qN)) errors.push(`direction_${f.direction}_not_in_evidence`);
    } else if (f.direction === 'unchanged') {
      if (!L.unchanged.test(sN) || !L.unchanged.test(qN)) errors.push('direction_unchanged_not_supported');
    }
    // actual vs estimate/forecast
    if (f.measure === 'estimate' || f.measure === 'forecast') {
      if (!L.estimate.test(sN)) errors.push('estimate_not_marked_in_statement');
      if (!L.estimate.test(qN)) errors.push('estimate_not_marked_in_evidence');
    } else if (L.estimate.test(sN)) {
      if (sNum.nums.filter(n => !n.isYear).length > 1) errors.push('actual_and_estimate_mixed_in_one_claim');
      else warnings.push('actual_claim_mentions_expectations');
    }
  }

  // --- attribution / causality / advice
  const isView = c.claim_type === 'attributed_view';
  if ((isView || c.claim_type === 'forecast_or_estimate') && !c.attribution) errors.push('attribution_missing');
  if (c.attribution) {
    const tokens = norm(c.attribution).split(/[^a-zà-ÿ0-9]+/).filter(w => w.length >= 5);
    if (tokens.length && !tokens.some(w => sN.includes(w))) errors.push('attribution_not_named_in_statement');
    if (isView && !L.speech.test(sN)) errors.push('attributed_view_without_speech_verb');
  }
  if (L.causal.test(sN) && !isView) errors.push('unattributed_causality');
  if (L.causal.test(sN) && isView && !L.causal.test(qN) && !L.speech.test(qN)) errors.push('causality_not_in_evidence');
  if (L.speculative.test(sN) && !c.attribution) warnings.push('speculative_wording_without_attribution');
  if (L.advice.test(sN)) errors.push('investment_advice_language');

  return {
    claim_id: `clm_${cyrb53(article.article_id + '|' + qN + '|' + sN)}`,
    local_id: c.local_id || `c${idx + 1}`,
    story_id: storyId,
    statement,
    claim_type: c.claim_type,
    attribution: c.attribution || null,
    source_article_id: article.article_id,   // attached in code, never by the model
    source_url: article.permalink,          // attached in code, never by the model
    publication: article.publication,
    figure: f,
    status: errors.length ? 'rejected' : 'verified',
    errors,
    warnings,
    internal: { evidence_quote: quote, evidence_location: location }, // never listener-facing
  };
});
}
// VALIDATE_CORE>>

// ---------------------------------------------------------------------------
// 1. parse model output
// ---------------------------------------------------------------------------
let extraction = null;
let extraction_error = null;
const choice = (resp.choices || [])[0];
if (!choice) extraction_error = 'no_choices_in_response';
else if (choice.message && choice.message.refusal) extraction_error = `model_refusal: ${choice.message.refusal}`;
else if (choice.finish_reason === 'length') extraction_error = 'truncated_output (raise OPENAI_MAX_COMPLETION_TOKENS or lower reasoning effort)';
else {
  try { extraction = JSON.parse(choice.message.content); }
  catch (e) { extraction_error = `invalid_json: ${e.message}`; }
}
const rawClaims = extraction && Array.isArray(extraction.claims) ? JSON.parse(JSON.stringify(extraction.claims)) : [];

// ---------------------------------------------------------------------------
// 2. optional fault injection (TEST_MODE) - applied to model output
// ---------------------------------------------------------------------------
const injected = [];
if (CONFIG.TEST_MODE === 'bad_quote' && rawClaims[0]) {
  rawClaims[0].evidence_quote = rawClaims[0].evidence_quote.replace(/rose/i, 'increased by'); // paraphrased quote
  injected.push(`bad_quote -> ${rawClaims[0].local_id}`);
}
if (CONFIG.TEST_MODE === 'wrong_basis') {
  const c = rawClaims.find(x => x.figure && x.figure.comparison_basis === 'year_over_year') || rawClaims.find(x => x.figure);
  if (c) {
    c.statement = `Norland producer prices rose ${c.figure.value_text} from the previous month.`; // quote untouched, still matches
    c.figure.comparison_basis = 'month_over_month';
    injected.push(`wrong_basis -> ${c.local_id}`);
  }
}

const storyId = `sty_${cyrb53(article.article_id)}`;
const claims = validateClaims(article, rawClaims, storyId);

// ---------------------------------------------------------------------------
// 4. usage log
// ---------------------------------------------------------------------------
const u = resp.usage || {};
const cached = (u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || 0;
const reasoning = (u.completion_tokens_details && u.completion_tokens_details.reasoning_tokens) || 0;
const price = CONFIG.PRICES.openai[CONFIG.OPENAI_MODEL];
const inTok = u.prompt_tokens || 0, outTok = u.completion_tokens || 0;
const costUsd = price
  ? ((inTok - cached) * price.input_per_1m + cached * price.cached_input_per_1m + outTok * price.output_per_1m) / 1e6
  : null;

const usage_log = [{
  run_id: prep.run_id,
  stage: 'extract_claims',
  article_id: article.article_id,
  cache_key: prep.cache_key,
  cache_hit: false,
  mocked: !!resp.mocked,
  model: resp.model || CONFIG.OPENAI_MODEL,
  input_tokens: inTok,
  cached_input_tokens: cached,
  output_tokens: outTok,
  reasoning_tokens: reasoning,
  est_cost_usd: costUsd === null ? null : Number(costUsd.toFixed(6)),
  price_known: !!price,
  escalated: false,
  retries: null, // HTTP node "Retry On Fail" does not expose the count
  logged_at: new Date().toISOString(),
}];

const verified = claims.filter(c => c.status === 'verified');
const rejected = claims.filter(c => c.status === 'rejected');

return [{
  json: {
    run_id: prep.run_id,
    extraction_error,
    injected_faults: injected,
    story: {
      story_id: storyId,
      title: article.headline, // internal label; not narrated as a claim
      event_date: extraction && extraction.event ? extraction.event.event_date_or_period : null,
      event_type: extraction && extraction.event ? extraction.event.event_type : null,
      entities: extraction && extraction.event ? extraction.event.primary_entities : [],
      topics: article.categories,
      article_ids: [article.article_id],
      editorial_score: null, // set in Workflow A ranking
      claim_ids: verified.map(c => c.claim_id),
    },
    counts: { extracted: claims.length, verified: verified.length, rejected: rejected.length },
    claims,
    usage_log,
  },
}];

// ============================================================================
// NODE: "Build script & gate"   (Code node, Run Once for All Items)
// Builds spoken segments ONLY from verified claims, then runs the final gate.
// FAIL-CLOSED: if anything fails, this node throws -> ElevenLabs never runs.
// ============================================================================
const prep = $('Prepare article & request').first().json;
const CONFIG = prep.config;
const article = prep.article;
const v = $input.first().json;

// ---------------------------------------------------------------------------
// helpers (keep in sync with "Validate claims")
// ---------------------------------------------------------------------------
// <<GATE_HELPERS (shared with Workflow B "Build script & gate")
const norm = s => String(s || '').normalize('NFKC')
  .replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[‐-―−]/g, '-')
  .replace(/ /g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
function extractNumbers(text, lang) {
  const t = norm(text);
  const times = [];
  const rest = t.replace(/\b(\d{1,2}):(\d{2})\b/g, m => { times.push(m); return ' '; });
  const decimalComma = ['de', 'nl', 'fr', 'es', 'it'].includes(lang);
  const SCALE = { trillion: 1e12, tn: 1e12, billion: 1e9, bn: 1e9, milliarden: 1e9, miljard: 1e9, million: 1e6, millionen: 1e6, miljoen: 1e6, mn: 1e6, m: 1e6, thousand: 1e3, k: 1e3 };
  const nums = [];
  const re = /-?\d+(?:[.,]\d+)*/g; let m;
  while ((m = re.exec(rest)) !== null) {
    const tok = m[0];
    const raw = decimalComma ? Number(tok.replace(/\.(?=\d{3}\b)/g, '').replace(',', '.')) : Number(tok.replace(/,(?=\d{3}\b)/g, ''));
    if (!Number.isFinite(raw)) continue;
    // "59 million", "$10.5bn", "65k" -> scaled value; the raw number is kept too
    const sc = rest.slice(m.index + tok.length).match(/^\s?(trillion|tn|billion|bn|milliarden|miljard|million|millionen|miljoen|mn|m|thousand|k)\b/);
    const v = sc ? raw * SCALE[sc[1]] : raw;
    nums.push({ tok: sc ? tok + ' ' + sc[1] : tok, v, raw, isYear: !sc && Number.isInteger(raw) && raw >= 1900 && raw <= 2100 && !/[.,]/.test(tok) });
  }
  return { nums, times };
}
const close = (a, b) => Math.abs(Math.abs(a) - Math.abs(b)) <= 1e-9 * Math.max(1, Math.abs(a), Math.abs(b));
const numIn = (x, list) => list.some(n => close(n.v, x) || close(n.raw, x));
const ADVICE = /\b(you should|investors should|traders should|should (buy|sell|invest|consider)|consider (buying|selling|adding)|(buy|sell) (now|the dip|signal)|good time to (buy|sell|invest)|worth buying|we recommend|recommend(s|ed)? (buying|selling)|strong (buy|sell)|go (long|short)|take profits?|price target|zacks rank|kaufempfehlung|koopadvies)\b/;
const CAUSAL = /\b(because|due to|driven by|caused by|thanks to|on the back of|triggered|sparked|fuell?ed by|led to|prompted|weighed on|boosted by|as a result|in response to|amid)\b/;

// Spoken form: only formatting changes, never new facts. Digits must survive unchanged.
function toSpoken(text) {
  return text
    .replace(/(\d)\s?%/g, '$1 percent')
    .replace(/\bm\/m\b/gi, 'month on month')
    .replace(/\by\/y\b/gi, 'year on year')
    .replace(/\bq\/q\b/gi, 'quarter on quarter')
    .replace(/(\d)\s?bps?\b/gi, '$1 basis points')
    .replace(/\s+/g, ' ')
    .trim();
}
const words = s => (s.match(/\S+/g) || []).length;
// GATE_HELPERS>>

// ---------------------------------------------------------------------------
// 1. select claims under the time budget (milestone 2: model order = newsworthiness)
// ---------------------------------------------------------------------------
const WORDS_PER_SECOND = 2.5; // ~150 wpm; calibrate after listening to real MP3s
const profile = CONFIG.PROFILE;
const verified = v.claims.filter(c => c.status === 'verified');
const byId = Object.fromEntries(v.claims.map(c => [c.claim_id, c]));

const d = new Date(CONFIG.BRIEFING_DATE + 'T12:00:00Z');
const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const dateSpoken = `${WEEKDAYS[d.getUTCDay()]}, ${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}`;

const segments = [];
segments.push({ kind: 'intro', template_id: 'intro_v1', display_text: `This is your markets briefing for ${dateSpoken}. It is read by an AI-generated voice.`, claim_ids: [] });
segments.push({ kind: 'transition', template_id: 'story_open_v1', display_text: `Our top story comes from ${article.publication}.`, claim_ids: [] });
const OUTRO = { kind: 'outro', template_id: 'outro_v1', display_text: 'That is the briefing. Every figure you heard links to its source article in the transcript. This is news, not investment advice.', claim_ids: [] };

const budgetWords = Math.floor(profile.duration_seconds * WORDS_PER_SECOND);
let used = words(segments.map(s => s.display_text).join(' ')) + words(OUTRO.display_text);
const dropped_for_time = [];
for (const c of verified) {
  const w = words(c.statement);
  if (used + w > budgetWords) { dropped_for_time.push(c.claim_id); continue; }
  segments.push({ kind: 'claim', template_id: null, display_text: c.statement, claim_ids: [c.claim_id] });
  used += w;
}
segments.push(OUTRO);

// fault injection: advisory sentence slipped into a factual segment
if (CONFIG.TEST_MODE === 'advice_in_script') {
  const seg = segments.find(s => s.kind === 'claim');
  if (seg) seg.display_text += ' Investors should consider buying the krone now.';
}

segments.forEach((s, i) => { s.index = i; s.spoken_text = toSpoken(s.display_text); });

// ---------------------------------------------------------------------------
// 2. final gate
// ---------------------------------------------------------------------------
const issues = [];
if (v.extraction_error) issues.push({ where: 'extraction', reason: v.extraction_error });
if (!verified.length) issues.push({ where: 'claims', reason: 'no_verified_claims' });
if (CONFIG.BLOCK_ON_ANY_REJECTED_CLAIM) {
  for (const c of v.claims.filter(x => x.status === 'rejected')) issues.push({ where: `claim ${c.local_id} (${c.claim_id})`, reason: c.errors.join(', ') });
}

for (const s of segments) {
  const where = `segment ${s.index} (${s.kind})`;
  const dN = norm(s.display_text);
  if (ADVICE.test(dN) || ADVICE.test(norm(s.spoken_text))) issues.push({ where, reason: 'investment_advice_language' });

  // spoken normalization must not change any digit
  const a = extractNumbers(s.display_text, 'en'), b = extractNumbers(s.spoken_text, 'en');
  if (a.nums.map(n => n.v).join('|') !== b.nums.map(n => n.v).join('|') || a.times.join('|') !== b.times.join('|')) {
    issues.push({ where, reason: 'spoken_normalization_changed_numbers' });
  }

  if (s.kind === 'claim') {
    if (!s.claim_ids.length) { issues.push({ where, reason: 'factual_segment_without_claim_id' }); continue; }
    const cs = s.claim_ids.map(id => byId[id]);
    if (cs.some(c => !c || c.status !== 'verified')) issues.push({ where, reason: 'segment_cites_unverified_claim' });
    const evid = cs.filter(Boolean).map(c => extractNumbers(c.internal.evidence_quote, article.language));
    const evNums = evid.flatMap(e => e.nums), evTimes = evid.flatMap(e => e.times);
    for (const n of a.nums) if (!n.isYear && !numIn(n.v, evNums)) issues.push({ where, reason: `number_not_supported:${n.tok}` });
    for (const t of a.times) if (!evTimes.includes(t)) issues.push({ where, reason: `time_not_supported:${t}` });
    if (CAUSAL.test(dN) && !cs.some(c => c && c.claim_type === 'attributed_view')) issues.push({ where, reason: 'unattributed_causality' });
  } else {
    if (!s.template_id) issues.push({ where, reason: 'non_factual_segment_not_from_template' });
    if (s.kind !== 'intro' && extractNumbers(s.display_text, 'en').nums.length) issues.push({ where, reason: 'numbers_in_non_factual_segment' });
  }
}

const tts_text = segments.map(s => s.spoken_text).join('\n\n');
if (tts_text.length > CONFIG.MAX_TTS_CHARS) issues.push({ where: 'script', reason: `too_long:${tts_text.length}>${CONFIG.MAX_TTS_CHARS}` });
if (CONFIG.SYNTHESIZE_AUDIO && /REPLACE/.test(CONFIG.ELEVENLABS_VOICE_ID)) issues.push({ where: 'config', reason: 'ELEVENLABS_VOICE_ID not set' });

if (issues.length) {
  const report = {
    run_id: prep.run_id,
    test_mode: CONFIG.TEST_MODE,
    injected_faults: v.injected_faults,
    counts: v.counts,
    issues,
    usage_log: v.usage_log,
  };
  throw new Error(`TTS BLOCKED - ${issues.length} issue(s): ` + issues.map(i => `[${i.where}] ${i.reason}`).join(' | ') + `\nREPORT ${JSON.stringify(report)}`);
}

// ---------------------------------------------------------------------------
// 3. approved output
// ---------------------------------------------------------------------------
return [{
  json: {
    run_id: prep.run_id,
    gate: { status: 'passed', checked_segments: segments.length, dropped_for_time },
    profile,
    story: v.story,
    claims: v.claims,
    usage_log: v.usage_log,
    script: {
      segments,
      tts_text,
      chars: tts_text.length,
      words: words(tts_text),
      est_duration_seconds: Math.round(words(tts_text) / WORDS_PER_SECOND),
    },
    tts: {
      enabled: !!CONFIG.SYNTHESIZE_AUDIO,
      voice_id: CONFIG.ELEVENLABS_VOICE_ID,
      output_format: CONFIG.ELEVENLABS_OUTPUT_FORMAT,
      body: { text: tts_text, model_id: CONFIG.ELEVENLABS_MODEL_ID },
    },
  },
}];

// ============================================================================
// NODE: "Package briefing"   (Code node, Run Once for All Items)
// Joins gate metadata with the MP3 (if synthesized). Produces the player
// payload: transcript segments with claim IDs + publisher links, and the usage log.
// Listener-facing payload contains NO source passages (licensing).
// ============================================================================
const prep = $('Prepare article & request').first().json;
const CONFIG = prep.config;
const article = prep.article;
const g = $('Build script & gate').first().json;   // metadata survives the binary-only TTS response
const inItem = $input.first();

// ---- audio ------------------------------------------------------------------
let binary = undefined;
let audio = { synthesized: false };
if (g.tts.enabled) {
  const bin = inItem.binary && inItem.binary.audio;
  if (!bin) throw new Error('ElevenLabs returned no binary "audio" - check HTTP node Response Format = File, output field = audio');
  bin.fileName = `briefing_${g.run_id}.mp3`;
  bin.mimeType = bin.mimeType || 'audio/mpeg';
  binary = { audio: bin };
  audio = { synthesized: true, file_name: bin.fileName, mime_type: bin.mimeType, file_size: bin.fileSize || null };
}

// ---- transcript (same validated segments that were spoken) ------------------
const byId = Object.fromEntries(g.claims.map(c => [c.claim_id, c]));
const transcript = g.script.segments.map(s => ({
  index: s.index,
  kind: s.kind,
  text: s.display_text,
  claim_ids: s.claim_ids,
  sources: s.claim_ids.map(id => ({
    claim_id: id,
    publication: byId[id].publication,
    headline: article.headline,
    url: byId[id].source_url,
  })),
}));

// ---- usage / cost -------------------------------------------------------------
const ttsChars = g.tts.enabled ? g.script.chars : 0;
const el = CONFIG.PRICES.elevenlabs;
const cpc = el.credits_per_char[CONFIG.ELEVENLABS_MODEL_ID];
const credits = cpc != null ? ttsChars * cpc : null;
const usage_log = [
  ...g.usage_log,
  {
    run_id: g.run_id,
    stage: 'tts',
    model: CONFIG.ELEVENLABS_MODEL_ID,
    billable_characters: ttsChars,
    est_credits: credits,
    est_cost_usd: credits != null && el.usd_per_1k_credits != null ? Number((credits / 1000 * el.usd_per_1k_credits).toFixed(6)) : null,
    cache_hit: false,
    logged_at: new Date().toISOString(),
  },
];
const llmUsd = usage_log.filter(r => r.stage !== 'tts').reduce((a, r) => a + (r.est_cost_usd || 0), 0);

return [{
  json: {
    run_id: g.run_id,
    briefing: {
      profile_id: g.profile.id,
      briefing_date: CONFIG.BRIEFING_DATE,
      disclosure: 'Narrated by an AI-generated voice. Script generated automatically from the linked articles.',
      est_duration_seconds: g.script.est_duration_seconds,
      audio,
      transcript,
    },
    claims_public: g.claims.map(c => ({
      claim_id: c.claim_id, statement: c.statement, status: c.status,
      source_url: c.source_url, publication: c.publication,
    })),
    debug_internal: { // team only - do not render in the player
      story: g.story,
      claim_checks: g.claims.map(c => ({ claim_id: c.claim_id, local_id: c.local_id, status: c.status, errors: c.errors, warnings: c.warnings, evidence: c.internal })),
      gate: g.gate,
      tts_text: g.script.tts_text,
    },
    usage: {
      rows: usage_log,
      totals: {
        llm_input_tokens: usage_log.reduce((a, r) => a + (r.input_tokens || 0), 0),
        llm_output_tokens: usage_log.reduce((a, r) => a + (r.output_tokens || 0), 0),
        llm_est_cost_usd: Number(llmUsd.toFixed(6)),
        tts_billable_characters: ttsChars,
        tts_est_credits: credits,
        elapsed_ms: Date.now() - prep.started_at_ms,
      },
    },
  },
  ...(binary ? { binary } : {}),
}];
